<script setup lang="ts">
import {onMounted,onUnmounted,watch,computed} from 'vue';
import {Grid,Clock,Setting,QuestionFilled,Connection,ArrowRight,Refresh,Check,FolderOpened,Monitor} from '@element-plus/icons-vue';
import {clampLogHeight} from '../domain/controllers';
import {useWorkbench} from './useWorkbench';
import ProjectStage from '../features/ProjectStage.vue';import BuildStage from '../features/BuildStage.vue';import InputStage from '../features/InputStage.vue';import AssemblyStage from '../features/AssemblyStage.vue';import EditorsStage from '../features/EditorsStage.vue';import RunStage from '../features/RunStage.vue';import HistoryView from '../features/HistoryView.vue';import SettingsView from '../features/SettingsView.vue';import HelpView from '../features/HelpView.vue';import LogDrawer from '../features/LogDrawer.vue';
const w=useWorkbench(),s=w.s;
const stages=[{title:'项目与环境',subtitle:'PROJECT',icon:'01'},{title:'程序准备',subtitle:'BUILD',icon:'02'},{title:'任务与输入',subtitle:'INPUTS',icon:'03'},{title:'装配与确认',subtitle:'ASSEMBLY',icon:'04'},{title:'参数与检查',subtitle:'VALIDATION',icon:'05'},{title:'运行与结果',subtitle:'RESULTS',icon:'06'}];
const projectName=computed(()=>String(s.state.project||'').split(/[\\/]/).filter(Boolean).at(-1)||'尚未选择项目');
const complete=(index:number)=>[!!s.state.project,!!s.state.build_workflow?.built,!!(s.job||s.city&&s.taskDir),w.flow.assemblyCurrent,w.flow.canRun,s.result?.verdict==='success'][index];
const currentTitle=computed(()=>s.view==='workbench'?stages[s.stage].title:s.view==='history'?'运行记录':s.view==='settings'?'环境与路径':'帮助与使用指南');
function previous(){s.stage=Math.max(0,s.stage-1);}function next(){s.stage=Math.min(5,s.stage+1);}
function fitLog(){s.logHeight=clampLogHeight(s.logHeight,window.innerHeight);}
watch(()=>s.logHeight,fitLog,{flush:'sync'});
onMounted(()=>{fitLog();window.addEventListener('resize',fitLog);void w.init();});
onUnmounted(()=>window.removeEventListener('resize',fitLog));
</script>
<template><div class="desktop-shell" data-testid="desktop-root" :class="{compact:s.preferences.compact_mode}"><aside class="sidebar"><div class="brand"><div class="brand-symbol"><el-icon :size="25"><Connection/></el-icon></div><div>LiShuttle<span>WORKFLOW DESKTOP</span></div></div><div class="workspace-caption">工程工作空间</div><nav class="main-navigation"><button data-testid="nav-workbench" :class="{selected:s.view==='workbench'}" @click="s.view='workbench'"><el-icon><Grid/></el-icon>工作台<span class="nav-dot"/></button><button data-testid="nav-history" :class="{selected:s.view==='history'}" @click="w.showHistory"><el-icon><Clock/></el-icon>运行记录</button><button data-testid="nav-settings" :class="{selected:s.view==='settings'}" @click="s.view='settings'"><el-icon><Setting/></el-icon>环境与路径</button><button data-testid="nav-help" :class="{selected:s.view==='help'}" @click="s.view='help'"><el-icon><QuestionFilled/></el-icon>帮助</button></nav><div class="sidebar-context"><span class="sidebar-label">当前项目</span><strong :title="s.state.project">{{projectName}}</strong><p>{{s.draft.PRESET||'未选择构建'}}</p><span class="sidebar-status"><i :class="{working:s.runtime.busy}"/>{{s.runtime.busy?'后台任务执行中':'本地工作空间'}}</span></div><div class="sidebar-footer"><el-icon><Monitor/></el-icon> {{s.info.version?'v'+s.info.version:'Desktop'}}<span>{{s.info.channel==='stable'?'STABLE':'DEV'}}</span></div></aside>
<div class="main-workspace"><header class="topbar"><div class="breadcrumb">工程工作台<el-icon><ArrowRight/></el-icon><strong>{{currentTitle}}</strong></div><div class="topbar-status"><span class="status-pill" :class="{busy:s.runtime.busy}"><i/>{{s.runtime.busy?(s.runtime.external?'外部实例占用':s.runtime.label||'运行中'):'服务已连接'}}</span><el-button :icon="Refresh" text @click="w.refresh" :disabled="!!s.pending||s.xmlDirty||s.csvDirty">刷新状态</el-button></div></header>
<section class="context-strip"><div><span class="context-label">当前项目</span><strong :title="s.state.project">{{projectName}}</strong></div><span class="context-divider"/><div><span class="context-label">构建配置</span><strong>{{s.state.preset||s.state.project_config?.PRESET||'待配置'}}</strong></div><span class="context-divider"/><div class="schema-context"><span class="context-label">运行 XML</span><strong :title="s.job?.schema">{{s.job?.schema||'尚未加载'}}</strong></div><div class="context-function" v-if="s.func">-f {{s.func}}<span>任务 {{s.taskId}}</span></div></section>
<div v-if="s.unknown" class="critical-banner" role="alert"><strong>操作结果待核对 · {{s.unknown.operation}}</strong><span>{{s.unknown.message}}</span><el-button size="small" @click="w.refresh" :disabled="s.xmlDirty||s.csvDirty||!!s.pending">刷新并核对状态</el-button></div><el-alert v-if="s.error" class="global-alert" :title="s.error" type="error" show-icon closable @close="s.error=''"/><el-alert v-else-if="s.notice" class="global-alert" :title="s.notice" type="success" show-icon closable @close="s.notice=''"/>
<div class="stage-navigation" v-if="s.view==='workbench'"><button :data-testid="'stage-'+index" v-for="(stage,index) in stages" :key="stage.icon" :class="{active:s.stage===index,complete:complete(index)}" @click="s.stage=index"><span class="step-number"><el-icon v-if="complete(index)"><Check/></el-icon><template v-else>{{stage.icon}}</template></span><span><small>{{stage.subtitle}}</small><strong>{{stage.title}}</strong></span><i v-if="index<5"/></button></div>
<main class="page-scroll" :style="{'padding-bottom':'30px','margin-bottom':'calc('+(s.view==='workbench'?'var(--stage-footer-height, 69px) + ':'')+(s.logOpen?s.logHeight:40)+'px)','scroll-padding-bottom':'16px','scroll-padding-top':'12px'}"><div v-if="!s.ready" class="loading-state"><el-skeleton :rows="8" animated/><p>正在连接本地工作空间…</p></div><template v-else><template v-if="s.view==='workbench'"><ProjectStage v-if="s.stage===0" :w="w"/><BuildStage v-else-if="s.stage===1" :w="w"/><InputStage v-else-if="s.stage===2" :w="w"/><AssemblyStage v-else-if="s.stage===3" :w="w"/><EditorsStage v-else-if="s.stage===4" :w="w"/><RunStage v-else :w="w"/></template><HistoryView v-else-if="s.view==='history'" :w="w"/><SettingsView v-else-if="s.view==='settings'" :w="w"/><HelpView v-else :w="w"/></template></main>
<footer v-if="s.view==='workbench'" class="stage-footer" :style="{bottom:(s.logOpen?s.logHeight:40)+'px'}"><div class="footer-hint"><span v-if="s.pending" class="spinner"/>{{s.operation||((s.xmlDirty||s.csvDirty)?'有未保存的编辑，请先保存或放弃。':w.runReason.value||'当前配置已通过检查，可以运行。')}}</div><el-button v-if="s.stage>0" @click="previous">上一步</el-button><el-button v-if="s.stage===0" data-testid="config-save" type="primary" @click="w.saveProject" :disabled="!s.state.project||!!s.pending||s.runtime.busy">保存项目配置</el-button><el-button v-else-if="s.stage===1" type="primary" @click="w.useExecutable" :disabled="!s.state.project||!!s.pending||s.runtime.busy">应用已有程序</el-button><el-button v-else-if="s.stage===2" type="primary" @click="s.mode==='existing'?w.activateXml():s.mode==='import'?w.previewImport():w.previewAssembly()" :disabled="!!s.pending||s.runtime.busy">{{s.mode==='existing'?'加载运行 XML':s.mode==='import'?'预览 XML 导入':'预览任务装配'}}</el-button><el-button v-else-if="s.stage===3" type="primary" @click="w.assemble" :disabled="!w.canApplyPreview()||!!s.pending||s.runtime.busy">确认装配</el-button><el-button v-else-if="s.stage===4" type="primary" @click="w.preflight" :disabled="!s.job||!!s.pending||s.runtime.busy||s.xmlDirty||s.csvDirty">运行前检查</el-button><el-button v-else type="primary" @click="w.startRun" :disabled="!!w.runReason.value">开始运行</el-button><el-button v-if="s.stage<5" @click="next" :icon="ArrowRight" circle title="下一阶段"/></footer><LogDrawer :w="w"/></div></div></template>
